actionConfiguration.body:
function (currentText, startText, endText, blocked) {
  const reasons = [];
  const codes = [];
  const cur = RoomChecker.toMin(currentText);
  const start = RoomChecker.toMin(startText);
  const end = RoomChecker.toMin(endText);
  if (blocked) {
    reasons.push("Room is blocked — Maintenance; no bookings can be checked.");
    codes.push("BLOCKED");
  }
  if (cur === null || start === null || end === null) {
    reasons.push("Enter all times as HH:MM, for example 14:30.");
    codes.push("INVALID_FORMAT");
    return {
      decision: "Unavailable",
      codes,
      reasons
    };
  }
  const wellFormed = start < end;
  if (!wellFormed) {
    reasons.push("Start time must be earlier than end time.");
    codes.push("INVALID_ORDER");
  } else {
    if (start <= cur) {
      reasons.push("Start time must be strictly after the current time.");
      codes.push("PAST_START");
    }
    const duration = end - start;
    if (duration > RoomChecker.MAX_DURATION) {
      reasons.push("Requested duration is " + duration + " min; the maximum allowed is " + RoomChecker.MAX_DURATION + " min.");
      codes.push("TOO_LONG");
    }
  }
  if (wellFormed && !blocked) {
    const overlaps = RoomChecker.bookings.filter(b => RoomChecker.toMin(b.start) < end && start < RoomChecker.toMin(b.end));
    if (overlaps.length > 0) {
      const list = overlaps.map(b => b.start + "–" + b.end).join(", ");
      reasons.push((overlaps.length > 1 ? "Overlaps with existing bookings: " : "Overlaps with existing booking: ") + list + ".");
      codes.push("OVERLAP");
    }
  }
  if (reasons.length === 0) {
    return {
      decision: "Available",
      codes: ["OK"],
      reasons: ["No conflicts, within bounds, and under the 120-minute limit."]
    };
  }
  return {
    decision: "Unavailable",
    codes,
    reasons
  };
}

